mapper.select:
SELECT sa.*, si.name AS supply_name, si.code AS supply_code, u1.real_name AS applicant_name, u1.department AS applicant_department, u2.real_name AS approver_name FROM supply_application sa LEFT JOIN supply_item si ON sa.supply_id = si.id LEFT JOIN sys_user u1 ON sa.applicant_id = u1.id LEFT JOIN sys_user u2 ON sa.approver_id = u2.id
AND sa.applicant_id = #{applicantId}
AND sa.status = #{status}
ORDER BY sa.apply_time DESC
